/**
 * Timeline = the fully resolved, frame-accurate cut.
 * Generated by build-timeline.ts and rendered by Remotion (remotion/Main.tsx).
 * Never edit by hand – always change edl.json and rebuild.
 * All `src` are relative to projects/ (Remotion public dir).
 */
import { z } from 'zod';

const Visual = z.union([
  z.object({ component: z.string(), props: z.record(z.string(), z.unknown()) }),
  z.object({ src: z.string(), trimBefore: z.number().int().default(0) }),
]);

export const TimelineClip = z.object({
  id: z.string(),
  kind: z.enum(['footage', 'generated']),
  from: z.number().int().min(0),
  duration: z.number().int().positive(),
  /** footage */
  src: z.string().optional(),
  trimBefore: z.number().int().min(0).default(0),
  zoom: z.number().default(1),
  /** Frame center after zoom (PUNCH: 0.575 = frame shifts down, the face stays in the upper part) */
  centerY: z.number().default(0.5),
  /** linear push as zoom fraction per second (shorts: 0.012) */
  push: z.number().default(0),
  focusX: z.number().default(0.5),
  focusY: z.number().default(0.5),
  /** separate (processed) audio; otherwise audio from src */
  audioSrc: z.string().optional(),
  audioTrimBefore: z.number().int().min(0).default(0),
  volume: z.number().default(1),
  /** generated (voice insert) */
  visual: Visual.optional(),
});
export type TimelineClip = z.infer<typeof TimelineClip>;

export const TimelineOverlay = z.object({
  id: z.string(),
  component: z.string(),
  layout: z.enum(['split', 'full', 'overlay']).default('overlay'),
  from: z.number().int().min(0),
  duration: z.number().int().positive(),
  props: z.record(z.string(), z.unknown()),
});
export type TimelineOverlay = z.infer<typeof TimelineOverlay>;

export const TimelineBRoll = z.object({
  id: z.string(),
  src: z.string(),
  from: z.number().int().min(0),
  duration: z.number().int().positive(),
  trimBefore: z.number().int().min(0),
  mode: z.enum(['full', 'pip']),
  volume: z.number(),
  isImage: z.boolean().default(false),
});

export const CaptionToken = z.object({
  text: z.string(),
  startMs: z.number(),
  endMs: z.number(),
  timestampMs: z.number().nullable(),
  confidence: z.number().nullable(),
});

export const TimelineAudio = z.object({
  src: z.string(),
  from: z.number().int().min(0),
  duration: z.number().int().positive(),
  trimBefore: z.number().int().min(0).default(0),
  volume: z.number(),
  fadeInFrames: z.number().int().min(0).default(0),
  fadeOutFrames: z.number().int().min(0).default(0),
  loop: z.boolean().default(false),
});

export const Timeline = z.object({
  version: z.literal(1),
  slug: z.string(),
  format: z.enum(['longform', 'short']),
  fps: z.number().positive(),
  width: z.number().int().positive(),
  height: z.number().int().positive(),
  durationInFrames: z.number().int().positive(),
  clips: z.array(TimelineClip),
  broll: z.array(TimelineBRoll).default([]),
  overlays: z.array(TimelineOverlay).default([]),
  captions: z.object({
    enabled: z.boolean(),
    style: z.enum(['short', 'longform']),
    tokens: z.array(CaptionToken),
  }),
  music: z.array(TimelineAudio).default([]),
  sfx: z.array(z.object({ name: z.string(), from: z.number().int(), volume: z.number() })).default([]),
  /** YouTube chapters from edl.sequence[].chapter */
  chapters: z.array(z.object({ from: z.number().int().min(0), title: z.string() })).default([]),
});
export type Timeline = z.infer<typeof Timeline>;
